//! TypeScript declarations derived from the public JSON presentation contracts.
use ts_rs::{Config, TS};

pub fn typescript() -> String {
    let config = Config::new().with_large_int("number");
    macro_rules! declarations {
        ($($ty:ty),+ $(,)?) => { vec![$(format!("export {}", <$ty>::decl(&config))),+] };
    }
    let declarations = declarations![
        crate::consumption::Tokens,
        crate::consumption::CostOrigin,
        crate::consumption::UsageCost,
        crate::consumption::UsageOrigin,
        crate::consumption::Granularity,
        crate::consumption::ConsumptionRecord,
        crate::consumption::ImportState,
        crate::consumption::SourceStatus,
        crate::consumption::UsageFilter,
        crate::consumption::ConsumptionTotal,
        crate::consumption::ConsumptionReport,
        crate::private_sync::SynchronizedAccount,
        crate::private_sync::LocalUsageSnapshot,
        crate::private_sync::LocalUsageSnapshotV2,
        crate::private_sync::LocalUsageAggregate,
        crate::private_sync::LocalUsageDay,
        crate::private_sync::LocalUsageModel,
        crate::private_sync::PrivateEvent,
        crate::private_sync::PrivateObservation,
        crate::private_sync::PrivateStoredObservation,
        crate::private_sync::PrivateRecentPage,
        crate::HistorySample,
        crate::HopRecord,
        crate::AccountScope,
        crate::Availability,
        crate::Freshness,
        crate::Observation<()>,
        crate::ResetCredit,
        crate::ResetInventory,
        crate::CreditBalance,
        crate::Capabilities,
        crate::ProviderDescriptor,
        crate::SharingConsent,
        crate::migration::CredentialKind,
        crate::migration::MigrationCandidate,
        crate::migration::MigrationSelection,
        crate::migration::MigrationAction,
        crate::migration::MigrationItem,
        crate::migration::MigrationReview,
        crate::migration::MigrationDirection,
        crate::migration::MigrationInvitation,
        crate::migration::MigrationSessionView,
        crate::MetricKind,
        crate::ProgressFormat,
        crate::BarChartPoint,
        crate::MetricLine,
        crate::ProviderOutput,
    ];
    format!("// Generated by fabrials-types; do not edit.\n// JSON timestamps use JavaScript numbers, not bigint.\n\n{}\n", declarations.join("\n\n").lines().map(str::trim_end).collect::<Vec<_>>().join("\n"))
}

#[cfg(test)]
mod tests {
    #[test]
    fn checked_in_types_match_rust_contracts() {
        assert_eq!(super::typescript(), include_str!("../bindings/contracts.ts"),
            "Run the contracts example to regenerate bindings/contracts.ts, then sync shared sources");
    }
}
